INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (1, 'msg_whatsapp', 'renovacao', NULL, 'Oi, {nome}! Sua renovação é em {data}: {valor}. PIX: {pix}. Pode me mandar o comprovante? Victor | VFITCOACH', 1);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (2, 'msg_whatsapp', 'falta', NULL, 'Oi, {nome}! Senti sua falta nos treinos (última aula em {data}). Está tudo bem? Vamos remarcar? Victor | VFITCOACH', 2);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (3, 'msg_whatsapp', 'boas_vindas', NULL, 'Oi, {nome}! Seja bem-vindo(a) à VFITCOACH! Fico feliz em começar essa jornada com você. Victor | VFITCOACH', 3);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (4, 'msg_whatsapp', 'reativacao', NULL, 'Oi, {nome}! Faz tempo que não nos falamos. Que tal retomarmos os treinos? Tenho novidades para você. Victor | VFITCOACH', 4);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (5, 'msg_whatsapp', 'cobranca', NULL, 'Oi, {nome}, tudo bem? Sua mensalidade de {valor}, vencida em {data}, ainda não constou aqui. Deve ter sido esquecimento, né? Segue o Pix atualizado.', 5);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (6, 'msg_whatsapp', 'indicacao', NULL, 'Oi, {nome}! Tá curtindo os treinos? Se você conhece alguém que quer começar, me indica! Quando a pessoa fechar, você ganha {vantagem} 🎁 Victor | VFITCOACH', 6);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (7, 'msg_whatsapp', 'dupla', NULL, 'Oi, {nome}! Que tal treinar com um amigo ou amiga? Em dupla o treino rende mais, é mais animado e vocês se cobram um ao outro. Quer trazer alguém? Victor | VFITCOACH', 7);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (8, 'msg_whatsapp', 'depoimento', NULL, 'Oi, {nome}! Seu treino comigo tem feito diferença? Você toparia me mandar um depoimento curto (texto ou vídeo)? {link_avaliacao} Obrigado! 🙏 Victor | VFITCOACH', 8);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (9, 'msg_dados', 'pix', NULL, '', 1);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (10, 'msg_dados', 'link_avaliacao', NULL, '', 2);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (11, 'msg_dados', 'vantagem', NULL, 'uma avaliação física grátis', 3);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (12, 'msg_dados', 'pix_nome', NULL, '', 4);
