INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (14, 'msg_dados', 'pix_banco', NULL, '', 6);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (15, 'msg_whatsapp', 'upsell', NULL, 'Oi, {nome}! Tenho uma proposta: {titulo}. Inclui: {inclui}. De {valor_normal} por {valor_oferta}/mês{duracao}{depois}.{ate} Quer aproveitar? Victor | VFITCOACH', 9);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (16, 'msg_whatsapp', 'cobranca_lembrete', NULL, 'Oi, {nome}! Tudo bem? Passando só pra lembrar que faltam {faltam} dias para o vencimento da sua mensalidade de {valor}, no dia {data}. O Pix está logo abaixo pra facilitar.', 10);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (17, 'msg_whatsapp', 'cobranca_hoje', NULL, 'Bom dia, {nome}! Hoje vence a sua mensalidade de {valor}. Consegue dar uma olhadinha? O Pix está logo abaixo.', 11);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (18, 'msg_whatsapp', 'cobranca_moderada', NULL, 'Oi, {nome}. Como estão as coisas? Sua mensalidade está vencida desde {data} ({dias} dias). Se aconteceu algum imprevisto, me avisa aqui pra gente dar um jeito.', 12);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (19, 'msg_whatsapp', 'cobranca_critica', NULL, '{nome}, sua mensalidade está vencida há mais de um mês (desde {data}). Me chama aqui pra fecharmos um acordo e evitar o bloqueio do serviço.', 13);
INSERT INTO "parametros" (id, grupo, chave, valor, valor_texto, ordem) VALUES (20, 'msg_whatsapp', 'cobranca_diferenca', NULL, 'Oi, {nome}! Recebi seu Pix de {pago} em {data}, obrigado! Como ele caiu depois do vencimento, ficou faltando {valor} de multa e juros. Segue o Pix da diferença.', 14);
